// src/components/ProductList.tsx
import React, { useEffect, useState } from 'react';
import apiService from '../services/api';
import { Product } from '../types';
import { useNavigate } from 'react-router-dom';
import './ProductList.css';

const ProductList: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [selectedProducts, setSelectedProducts] = useState<number[]>([]);
  const navigate = useNavigate();

  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    try {
      setLoading(true);
      const data = await apiService.getProducts();
      setProducts(data);
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to load products');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: number) => {
    if (!window.confirm('Are you sure you want to delete this product?')) return;
    try {
      await apiService.deleteProduct(id);
      fetchProducts();
    } catch (err: any) {
      alert(err.response?.data?.error || 'Failed to delete product');
    }
  };

  const handleBulkDelete = async () => {
    if (!window.confirm(`Delete ${selectedProducts.length} products?`)) return;
    try {
      await Promise.all(selectedProducts.map(id => apiService.deleteProduct(id)));
      setSelectedProducts([]);
      fetchProducts();
    } catch (err: any) {
      alert('Failed to delete some products');
    }
  };

  const toggleSelect = (id: number) => {
    setSelectedProducts(prev =>
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  if (loading) return <div className="loading">Loading...</div>;
  if (error) return <div className="error">{error}</div>;

  return (
    <div className="product-list">
      <div className="list-header">
        <h2>Products</h2>
        <div className="actions">
          {selectedProducts.length > 0 && (
            <button onClick={handleBulkDelete} className="btn-danger">
              Delete Selected ({selectedProducts.length})
            </button>
          )}
          <button onClick={() => navigate('/products/new')} className="btn-primary">
            Add Product
          </button>
        </div>
      </div>
      <table className="product-table">
        <thead>
          <tr>
            <th width="40">
              <input
                type="checkbox"
                onChange={(e) => {
                  if (e.target.checked) {
                    setSelectedProducts(products.map(p => p.id!));
                  } else {
                    setSelectedProducts([]);
                  }
                }}
              />
            </th>
            <th>Image</th>
            <th>Name</th>
            <th>Category</th>
            <th>Price</th>
            <th>Stock</th>
            <th>Rating</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>
                <input
                  type="checkbox"
                  checked={selectedProducts.includes(product.id!)}
                  onChange={() => toggleSelect(product.id!)}
                />
              </td>
              <td>
                {product.image_url ? (
                  <img src={product.image_url} alt={product.name} className="product-thumb" />
                ) : (
                  <div className="no-image">No Image</div>
                )}
              </td>
              <td>{product.name}</td>
              <td>{product.category_name}</td>
              <td>${product.price.toFixed(2)}</td>
              <td>{product.stock || 0}</td>
              <td>{product.rating?.toFixed(1) || 'N/A'}</td>
              <td>
                <button onClick={() => navigate(`/products/edit/${product.id}`)} className="btn-small">
                  Edit
                </button>
                <button onClick={() => handleDelete(product.id!)} className="btn-small btn-danger">
                  Delete
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default ProductList;
