// src/components/CategoryManagement.tsx
import React, { useState, useEffect } from 'react';
import apiService from '../services/api';
import { Category } from '../types';
import './CategoryManagement.css';

const CategoryManagement: React.FC = () => {
  const [categories, setCategories] = useState<Category[]>([]);
  const [showForm, setShowForm] = useState(false);
  const [editId, setEditId] = useState<number | null>(null);
  const [formData, setFormData] = useState<Category>({ name: '', description: '' });

  useEffect(() => {
    fetchCategories();
  }, []);

  const fetchCategories = async () => {
    try {
      const data = await apiService.getCategories();
      setCategories(data);
    } catch (err) {
      alert('Failed to load categories');
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (editId) {
        await apiService.updateCategory(editId, formData);
      } else {
        await apiService.createCategory(formData);
      }
      setFormData({ name: '', description: '' });
      setEditId(null);
      setShowForm(false);
      fetchCategories();
    } catch (err: any) {
      alert(err.response?.data?.error || 'Failed to save category');
    }
  };

  const handleEdit = (category: Category) => {
    setFormData({ name: category.name, description: category.description });
    setEditId(category.id!);
    setShowForm(true);
  };

  const handleDelete = async (id: number) => {
    if (!window.confirm('Delete this category?')) return;
    try {
      await apiService.deleteCategory(id);
      fetchCategories();
    } catch (err) {
      alert('Failed to delete category');
    }
  };

  return (
    <div className="category-management">
      <div className="header">
        <h2>Categories</h2>
        <button onClick={() => { setShowForm(!showForm); setEditId(null); setFormData({ name: '', description: '' }); }} className="btn-primary">
          {showForm ? 'Cancel' : 'Add Category'}
        </button>
      </div>

      {showForm && (
        <form onSubmit={handleSubmit} className="category-form">
          <div className="form-group">
            <label>Name</label>
            <input
              type="text"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              required
            />
          </div>
          <div className="form-group">
            <label>Description</label>
            <textarea
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
            />
          </div>
          <button type="submit" className="btn-primary">{editId ? 'Update' : 'Create'}</button>
        </form>
      )}

      <div className="category-list">
        {categories.map(cat => (
          <div key={cat.id} className="category-card">
            <h3>{cat.name}</h3>
            <p>{cat.description}</p>
            <div className="actions">
              <button onClick={() => handleEdit(cat)} className="btn-small">Edit</button>
              <button onClick={() => handleDelete(cat.id!)} className="btn-small btn-danger">Delete</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default CategoryManagement;
