// src/services/api.ts
import axios, { AxiosInstance } from 'axios';

const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

class ApiService {
  private api: AxiosInstance;

  constructor() {
    this.api = axios.create({
      baseURL: API_BASE_URL,
      headers: { 'Content-Type': 'application/json' }
    });

    this.api.interceptors.request.use((config) => {
      const token = localStorage.getItem('customer_token');
      if (token) {
        config.headers.Authorization = `Bearer ${token}`;
      }
      return config;
    });
  }

  async getProducts(filters?: {
    category_id?: number;
    min_price?: number;
    max_price?: number;
    min_rating?: number;
    search?: string;
  }) {
    const response = await this.api.get('/products', { params: filters });
    return response.data;
  }

  async getProduct(id: number) {
    const response = await this.api.get(`/products/${id}`);
    return response.data;
  }

  async getCategories() {
    const response = await this.api.get('/categories');
    return response.data;
  }

  async getRecommendations() {
    const response = await this.api.get('/recommendations');
    return response.data;
  }

  async getCart() {
    const response = await this.api.get('/cart');
    return response.data;
  }

  async addToCart(productId: number, quantity: number = 1) {
    const response = await this.api.post('/cart', { product_id: productId, quantity });
    return response.data;
  }

  async updateCartItem(id: number, quantity: number) {
    const response = await this.api.put(`/cart/${id}`, { quantity });
    return response.data;
  }

  async removeFromCart(id: number) {
    const response = await this.api.delete(`/cart/${id}`);
    return response.data;
  }

  async login(email: string, password: string) {
    const response = await this.api.post('/auth/login', { email, password });
    return response.data;
  }

  async register(email: string, password: string) {
    const response = await this.api.post('/auth/register', { email, password });
    return response.data;
  }
}

export default new ApiService();
