### 4. Cart Context

```typescript
// src/contexts/CartContext.tsx
import React, { createContext, useContext, useState, useEffect } from 'react';
import apiService from '../services/api';
import { CartItem } from '../types';

interface CartContextType {
  cart: CartItem[];
  cartCount: number;
  isAuthenticated: boolean;
  addToCart: (productId: number, quantity?: number) => Promise<void>;
  updateQuantity: (id: number, quantity: number) => Promise<void>;
  removeItem: (id: number) => Promise<void>;
  refreshCart: () => Promise<void>;
  login: (email: string, password: string) => Promise<void>;
  logout: () => void;
}

const CartContext = createContext<CartContextType | undefined>(undefined);

export const CartProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  useEffect(() => {
    const token = localStorage.getItem('customer_token');
    if (token) {
      setIsAuthenticated(true);
      refreshCart();
    } else {
      loadLocalCart();
    }
  }, []);

  const loadLocalCart = () => {
    const localCart = localStorage.getItem('local_cart');
    if (localCart) {
      setCart(JSON.parse(localCart));
    }
  };

  const saveLocalCart = (items: CartItem[]) => {
    localStorage.setItem('local_cart', JSON.stringify(items));
  };

  const refreshCart = async () => {
    try {
      const data = await apiService.getCart();
      setCart(data);
    } catch (err) {
      console.error('Failed to load cart');
    }
  };

  const addToCart = async (productId: number, quantity: number = 1) => {
    try {
      if (isAuthenticated) {
        await apiService.addToCart(productId, quantity);
        await refreshCart();
      } else {
        // Local cart for non-authenticated users
        const newCart = [...cart];
        const existing = newCart.find(item => item.product_id === productId);
        if (existing) {
          existing.quantity += quantity;
          existing.subtotal = existing.product_price * existing.quantity;
        }
        setCart(newCart);
        saveLocalCart(newCart);
      }
    } catch (err) {
      throw new Error('Failed to add to cart');
    }
  };

  const updateQuantity = async (id: number, quantity: number) => {
    try {
      if (isAuthenticated) {
        await apiService.updateCartItem(id, quantity);
        await refreshCart();
      } else {
        const newCart = cart.map(item => 
          item.id === id ? { ...item, quantity, subtotal: item.product_price * quantity } : item
        );
        setCart(newCart);
        saveLocalCart(newCart);
      }
    } catch (err) {
      throw new Error('Failed to update cart');
    }
  };

  const removeItem = async (id: number) => {
    try {
      if (isAuthenticated) {
        await apiService.removeFromCart(id);
        await refreshCart();
      } else {
        const newCart = cart.filter(item => item.id !== id);
        setCart(newCart);
        saveLocalCart(newCart);
      }
    } catch (err) {
      throw new Error('Failed to remove item');
    }
  };

  const login = async (email: string, password: string) => {
    const data = await apiService.login(email, password);
    localStorage.setItem('customer_token', data.access_token);
    setIsAuthenticated(true);
    await refreshCart();
  };

  const logout = () => {
    localStorage.removeItem('customer_token');
    setIsAuthenticated(false);
    setCart([]);
  };

  return (
    <CartContext.Provider value={{
      cart,
      cartCount: cart.reduce((sum, item) => sum + item.quantity, 0),
      isAuthenticated,
      addToCart,
      updateQuantity,
      removeItem,
      refreshCart,
      login,
      logout
    }}>
      {children}
    </CartContext.Provider>
  );
};

export const useCart = () => {
  const context = useContext(CartContext);
  if (!context) throw new Error('useCart must be used within CartProvider');
  return context;
};
