import React, { useState } from 'react';
import { Category, Filters } from '../types';
import './FilterPanel.css';

interface Props {
  categories: Category[];
  filters: Filters;
  onFilterChange: (filters: Filters) => void;
}

const FilterPanel: React.FC<Props> = ({ categories, filters, onFilterChange }) => {
  const [localFilters, setLocalFilters] = useState<Filters>(filters);

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const search = e.target.value;
    const newFilters = { ...localFilters, search: search || undefined };
    setLocalFilters(newFilters);
    onFilterChange(newFilters);
  };

  const handleCategoryChange = (categoryId: number | undefined) => {
    const newFilters = { ...localFilters, category_id: categoryId };
    setLocalFilters(newFilters);
    onFilterChange(newFilters);
  };

  const handlePriceChange = (min?: number, max?: number) => {
    const newFilters = { ...localFilters, min_price: min, max_price: max };
    setLocalFilters(newFilters);
    onFilterChange(newFilters);
  };

  const handleRatingChange = (rating?: number) => {
    const newFilters = { ...localFilters, min_rating: rating };
    setLocalFilters(newFilters);
    onFilterChange(newFilters);
  };

  const clearFilters = () => {
    setLocalFilters({});
    onFilterChange({});
  };

  return (
    <div className="filter-panel">
      <h3>Filters</h3>

      <div className="filter-section">
        <label>Search</label>
        <input
          type="text"
          placeholder="Search products..."
          value={localFilters.search || ''}
          onChange={handleSearchChange}
        />
      </div>

      <div className="filter-section">
        <label>Category</label>
        <select
          value={localFilters.category_id || ''}
          onChange={(e) => handleCategoryChange(e.target.value ? Number(e.target.value) : undefined)}
        >
          <option value="">All Categories</option>
          {categories.map(cat => (
            <option key={cat.id} value={cat.id}>{cat.name}</option>
          ))}
        </select>
      </div>

      <div className="filter-section">
        <label>Price Range</label>
        <div className="price-inputs">
          <input
            type="number"
            placeholder="Min"
            value={localFilters.min_price || ''}
            onChange={(e) => handlePriceChange(e.target.value ? Number(e.target.value) : undefined, localFilters.max_price)}
          />
          <span>-</span>
          <input
            type="number"
            placeholder="Max"
            value={localFilters.max_price || ''}
            onChange={(e) => handlePriceChange(localFilters.min_price, e.target.value ? Number(e.target.value) : undefined)}
          />
        </div>
      </div>

      <div className="filter-section">
        <label>Minimum Rating</label>
