```typescript
// src/pages/ShoppingCart.tsx
import React from 'react';
import { useCart } from '../contexts/CartContext';
import { Link } from 'react-router-dom';
import './ShoppingCart.css';

const ShoppingCart: React.FC = () => {
  const { cart, updateQuantity, removeItem } = useCart();

  const total = cart.reduce((sum, item) => sum + item.subtotal, 0);

  if (cart.length === 0) {
    return (
      <div className="empty-cart">
        <h2>Your cart is empty</h2>
        <Link to="/" className="continue-shopping">Continue Shopping</Link>
      </div>
    );
  }

  return (
    <div className="shopping-cart">
      <h1>Shopping Cart</h1>

      <div className="cart-items">
        {cart.map(item => (
          <div key={item.id} className="cart-item">
            <img src={item.product_image || '/placeholder.png'} alt={item.product_name} />
            <div className="item-details">
              <h3>{item.product_name}</h3>
              <p className="item-price">${item.product_price.toFixed(2)}</p>
            </div>
            <div className="item-quantity">
              <input
                type="number"
                min="1"
                value={item.quantity}
                onChange={(e) => updateQuantity(item.id, Number(e.target.value))}
              />
            </div>
            <div className="item-subtotal">
              ${item.subtotal.toFixed(2)}
            </div>
            <button onClick={() => removeItem(item.id)} className="remove-btn">×</button>
          </div>
        ))}
      </div>

      <div className="cart-summary">
        <h3>Order Summary</h3>
        <div className="summary-row">
          <span>Subtotal:</span>
          <span>${total.toFixed(2)}</span>
        </div>
        <div className="summary-row total">
          <span>Total:</span>
          <span>${total.toFixed(2)}</span>
        </div>
        <button className="checkout-btn">Proceed to Checkout</button>
      </div>
    </div>
  );
};

export default ShoppingCart;
